CREATE TABLE public.users (
    id bigserial PRIMARY KEY,
    name varchar(255) NOT NULL,
    email varchar(255) NOT NULL,
    email_verified_at timestamp(0) without time zone,
    password varchar(255) NOT NULL,
    remember_token varchar(100),
    phone varchar(40),
    loyalty_tier varchar(20) NOT NULL DEFAULT 'member',
    loyalty_points integer NOT NULL DEFAULT 0 CHECK (loyalty_points >= 0),
    is_admin boolean NOT NULL DEFAULT false,
    date_of_birth date,
    gender varchar(20),
    preferred_language varchar(10) NOT NULL DEFAULT 'en',
    preferred_store varchar(255),
    marketing_preferences json,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone
);
CREATE UNIQUE INDEX users_email_unique ON public.users (email);

CREATE TABLE public.password_reset_tokens (
    email varchar(255) PRIMARY KEY,
    token varchar(255) NOT NULL,
    created_at timestamp(0) without time zone
);

CREATE TABLE public.sessions (
    id varchar(255) PRIMARY KEY,
    user_id bigint,
    ip_address varchar(45),
    user_agent text,
    payload text NOT NULL,
    last_activity integer NOT NULL
);
CREATE INDEX sessions_user_id_index ON public.sessions (user_id);
